import { stdout } from std.io;
class Oops implements Throwable {
    inmut reason: String;
    construct(reason: String) { this.reason = reason; }
    message(): String { return this.reason; }
    code(): String { return "OOPS"; }
    cause(): Error? { return null; }
    stack_trace(): StackTrace { return StackTrace(); }
}
fn check(n: Int32): Int32 throws Oops {
    if n < 0 { throw Oops("negative"); }
    return n;
}
class Svc {
    construct() { }
    run(n: Int32): Void {
        try {
            inmut v = check(n);
            stdout.println("ok " + v.to_string());
        } catch Oops(e) {
            stdout.println("failed " + e.message());
        } finally {
            stdout.println("cleanup " + n.to_string());
        }
    }
}
fn main(): Void {
    inmut s = Svc();
    s.run(2);
    s.run(-1);
}
